mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p;
  q.xz = rot(time * 0.3) * q.xz;
  float beat = sin(time * 4.0) * 0.08;
  float egg = length(vec3(q.xz, q.y * 0.6)) - (0.9 + beat);
  float threads = length(abs(p.xz) - 0.5) - 0.02;
  return min(egg, threads);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.04, 0.02, 0.01);
  if (t < 7.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(1.0, 1.5, -2.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
    col = vec3(0.15, 0.08, 0.02) + diff * vec3(0.9, 0.5, 0.1) + spec * vec3(1.0, 0.8, 0.5);
  }
  ret = col;
}
